\u0042\u0071\u0044\u0051\u0020\u0075\u0042\u0021\u0040\u0059\u0023\u0058\u006b\u004e\u0049\u0058\u0052\u004a\u002f\u007a\u0031\u0062\u0041\u0040\u0048\u0036\u0036\u0054\u005d\u007d\u004e\u007e\u005a\u0073\u007b\u0067\u0028\u0027\u0064\u004e\u0059\u0057\u006b\u0061\u0076\u006a\u0051\u0048\u0049\u002c\u002e\u0041\u0051\u003d\u0045\u0043\u0029\u0058\u0061\u007e\u004a\u005b\u006c\u0020\u0072\u0078\u0059\u0069\u004d\u007c\u006d\u0035\u003f\u004c\u006f\u003b\u0033\u0022\u002f\u0079\u0051\u0065\u0042\u007c\u0042\u004c\u002a\u0033\u0031\u0030\u0040\u002e\u0040\u004e\u0049\u0047\u003b\u0076\u0047\u007c\u0027\u0021\u0035\u002a\u0052\u004e\u0021\u0035\u002f\u0041\u002a\u0072\u0034\u0067\u0056\u0070\u002e\u0056\u0021\u0063\u0057\u0051\u0031\u0078\u002e\u0077\u004f\u0024\u0037\u006c\u0056\u0038\u0030\u004c\u0031\u006a\u0022\u0073\u004d\u004e\u004f\u0066\u0043\u007e\u0059\u0056\u0059\u0062\u007b\u007d\u006a\u0062\u0028\u003c\u0068\u005c\u0035\u0058\u003c\u005f\u0028\u0071\u002c\u0037\u0046\u0054\u006d\u0021\u0071\u003f\u006e\u002c\u0056\u005d\u0058\u005e\u0032\u0047\u003f\u003d\u005f\u0023\u006e\u004d\u0065\u006c\u0028\u006e\u0060\u003a\u0024\u005b\u0075\u0068\u0020\u004e\u0028\u002e\u0057\u005b\u007e\u0058\u005e\u0060\u003a\u0068\u0071\u007d\u006b\u0073\u003b\u0056\u0079\u0043\u0034\u0052\u0024\u0039\u002a\u005a\u0025\u006a\u002c\u003a\u0078\u007c\u002f\u004f\u0063\u0071\u0054\u003c\u0057\u0062\u002a\u0034\u0073\u0051\u0034\u0078\u007b\u005f\u0029\u005a\u002e\u0060\u0045\u004b\u006a\u003b\u006c\u006c\u004f\u0040\u0072\u0035\u0022\u0039\u0043\u0041\u0051\u0048\u007d\u0028\u0037\u003d\u0037\u003c\u0065\u0066\u0071\u007c\u0060\u0054\u0053\u0050\u003c\u005a\u0072\u006f\u0057\u0041\u0032\u0079\u005f\u0073\u006d\u0031\u0065\u0036\u007c\u0053\u0023\u0070\u0076\u0048\u006f\u0076\u007e\u0057\u005a\u004c\u003d\u0033\u007c\u0076\u0050\u0048\u0023\u0033\u003e\u0039\u002f\u0050\u0032\u007e\u002b\u0067\u0062\u0058\u0049\u0025\u0051\u0055\u0074\u0078\u0032\u0078\u0027\u006c\u0062\u006a\u0024\u004c\u0056\u0020\u005e\u0054\u007b\u005c\u0020\u004b\u004f\u0024\u0029\u002b\u004a\u0025\u0066\u006c\u0022\u007a\u005e\u006a\u005a\u0050\u006b\u0071\u0054\u0033\u0077\u0064\u0034\u006b\u0037\u0060\u0078\u0052\u004e\u007b\u0030\u0079\u004d\u003b\u0064\u005a\u0069\u0066\u0028\u0066\u0032\u0037\u0021\u0071\u002b\u003b\u0053\u0071\u004a\u0065\u0065\u002b\u005b\u004d\u003f\u005b\u003e\u002d\u005c\u0038\u005a\u0078\u0059\u0058\u007d\u007b\u0078\u0071\u007b\u004a\u0027\u0051\u0053\u0065\u0020\u0077\u004c\u004b\u006a\u005f\u0025\u006c\u0056\u003f\u0023\u0045\u0021\u007d\u0044\u0051\u0067\u0045\u0032\u0076\u0064\u0030\u006a\u002f\u0024\u005e\u0041\u0041\u0023\u004d\u0031\u005c\u003c\u005d\u006f\u0049\u0058\u002a\u0074\u0039\u0064\u0045\u0046\u0023\u004e\u006f\u0067\u0069\u0035\u002d\u002f\u0051\u0070\u0058\u0055\u0075\u004d\u006c\u0077\u007d\u0038\u0043\u0042\u0054\u005d\u0023\u005f\u0074\u0046\u0064\u0031\u005b\u0064\u0031\u0022\u0079\u002b\u0026\u003d\u0022\u0074\u004f\u0048\u0061\u007e\u002b\u0079\u0065\u003e\u0042\u0062\u007a\u0043\u0059\u0047\u002c\u006b\u003b\u0033\u0035\u0036\u0057\u0061\u002f\u0074\u0030\u0037\u004d\u0059\u004e\u0078\u0079\u005f\u007a\u0028\u0029\u0078\u007c\u0033\u0036\u0043\u003b\u0072\u0077\u0025\u0078\u0044\u006a\u004c\u0060\u006b\u0033\u0063\u0066\u0052\u0072\u004f\u003e\u0075\u007e\u005b\u0020\u0068\u003a\u0064\u003a\u004e\u004d\u0034\u005f\u003d\u004c\u0068\u0057\u0069\u004d\u0035\u0040\u004f\u005a\u0036\u0033\u0044\u005d\u0078\u0046\u0077\u0057\u0030\u0022\u0049\u002c\u0059\u0052\u0056\u004e\u002d\u0048\u003a\u005d\u004a\u0023\u0027\u0037\u0051\u0047\u003a\u0028\u0047\u0059\u0072\u0021\u0064\u0030\u0057\u007e\u005b\u005c\u0034\u0072\u004d\u003d\u0041\u007c\u0079\u0052\u0054\u0048\u0050\u0027\u0077\u004b\u002c\u003a\u0029\u0041\u004c\u0063\u0068\u0054\u0075\u0038\u0051\u005c\u0028\u0064\u004b\u007c\u0057\u004e\u0053\u0023\u002a\u005a\u003f\u0036\u005a\u0041\u005c\u003c\u003a\u007c\u002e\u0038\u0063\u0048\u0043\u0053\u006f\u0068\u007d\u0043\u0054\u0077\u0033\u003f\u0030\u0061\u002e\u0077\u002f\u0022\u003e\u0023\u0027\u007d\u0074\u005a\u0035\u005f\u0065\u0030\u0055\u0024\u0053\u003e\u0024\u0059\u0047\u003d\u0022\u0035\u0030\u0065\u003d\u0060\u0046\u0067\u0067\u006b\u0075\u0032\u0061\u002a\u004f\u003b\u0055\u007b\u0053\u006a\u0027\u0063\u004c\u003b\u0046\u005f\u0079\u0058\u003d\u0076\u002c\u007c\u0077\u004d\u0039\u004f\u0069\u006c\u0027\u0027\u002a\u0024\u007a\u0039\u002b\u0070\u004a\u005e\u0072\u006e\u0061\u006d\u0077\u0026\u0075\u005b\u0033\u0042\u005b\u003f\u0079\u006a\u0039\u0077\u0042\u0058\u007c\u0048\u0050\u0039\u0050\u0047\u0056\u0077\u0035\u0052\u007b\u0058\u0072\u006e\u0058\u0053\u002d\u002c\u0061\u0054\u0069\u007d\u0058\u004f\u0064\u006c\u0056\u004d\u0035\u0068\u0022\u004b\u0033\u0021\u004a\u0075\u0074\u006f\u0054\u0031\u0072\u004c\u0024\u0070\u0030\u004a\u0036\u0024\u0030\u006b\u004c\u006c\u0027\u0063\u0066\u0023\u0040\u0039\u0028\u0054\u0029\u0024\u0045\u0027\u005e\u0052\u0031\u0021\u0072\u006d\u0059\u0043\u0051\u0032\u0044\u0020\u0030\u002a\u0078\u004a\u0037\u0067\u0074\u0023\u0031\u0073\u0043\u006f\u003c\u0053\u0045\u0060\u004b\u0061\u0066\u0021\u0037\u0046\u0052\u0033\u0047\u004c\u0061\u0039\u0070\u0021\u002c\u002d\u002e\u0030\u005d\u0077\u0028\u0049\u0023\u0065\u006d\u0022\u0029\u006d\u002d\u006c\u0077\u0043\u002f\u0066\u0023\u0058\u0029\u0056\u0056\u002d\u0037\u0079\u002f\u005c\u0039\u0040\u007d\u006f\u0048\u0057\u006f\u0075\u0073\u0042\u0042\u0049\u0042\u005d\u007b\u0027\u002d\u005c\u006d\u0061\u006a\u0075\u0061\u0043\u0052\u0050\u003f\u0029\u007b\u0031\u007a\u0041\u0035\u005c\u006a\u0064\u0023\u0049\u0042\u0064\u0038\u0078\u006f\u007d\u006d\u0072\u0029\u0079\u0078\u0044\u004b\u0066\u0027\u007b\u0028\u0054\u0054\u0033\u0041\u0074\u0079\u007a\u006e\u0056\u0022\u0066\u005c\u0048\u004f\u0043\u003c\u0044\u0061\u0050\u003f\u0064\u0071\u0028\u0051\u0059\u005e\u005a\u0077\u0063\u0066\u0072\u007a\u0071\u004c\u0073\u005d\u0051\u005f\u004c\u004f\u004e\u004c\u004b\u0044\u0039\u0066\u007b\u002d\u003d\u0024\u005a\u0055\u004c\u007b\u0063\u0033\u0028\u0028\u004e\u0078\u0022\u0053\u0038\u0044\u0028\u004b\u0021\u002b\u0051\u0038\u0028\u004c\u0022\u0028\u0074\u0059\u0064\u0047\u005c\u0031\u0032\u006b\u0046\u0066\u0028\u0035\u0058\u006d\u0025\u0044\u0062\u0071\u0051\u0074\u0044\u0066\u0038\u0047\u003a\u0048\u0051\u007e\u0063\u0029\u002f\u004a\u002e\u006c\u0054\u007c\u006e\u002c\u0027\u0028\u004e\u0079\u0057\u0039\u0060\u0074\u003f\u0072\u006f\u004e\u006a\u0020\u0061\u002a\u0026\u004d\u003a\u0079\u0027\u0062\u0048\u004f\u003a\u0035\u0030\u002b\u003f\u0042\u0033\u0035\u002a\u0035\u007b\u0068\u004f\u002e\u003d\u0079\u005f\u0054\u0022\u003e\u0055\u0060\u005a\u002f\u0034\u003f\u004e\u0054\u006a\u005d\u0046\u0048\u0029\u0041\u002a\u0023\u005b\u0033\u0029\u0032\u007b\u0067\u004b\u002d\u0051\u0079\u002b\u006b\u007c\u0066\u0031\u0070\u0058\u0023\u0041\u0025\u0040\u0034\u007c\u006b\u0026\u0033\u0045\u0048\u002e\u0068\u0055\u0060\u0057\u0050\u0044\u004a\u0070\u007d\u0055\u0058\u0038\u0049\u005a\u005b\u0034\u0078\u0054\u007c\u0045\u007d\u0062\u0079\u0075\u0069\u0020\u0042\u007b\u005a\u0037\u0079\u006c\u0044\u003f\u0063\u0063\u004a\u0051\u0045\u003c\u004a\u0061\u004b\u005a\u005d\u0033\u0043\u0059\u0020\u003f\u003b\u006a\u007a\u0023\u0036\u0066\u0077\u0059\u0054\u0050\u005e\u003a\u0059\u002b\u0070\u006f\u0045\u006f\u003c\u004e\u0078\u002c\u0062\u0023\u0035\u0073\u003f\u005a\u0061\u0077\u0028\u002d\u007c\u0077\u005c\u0066\u003f\u0027\u004d\u0037\u004d\u007a\u004f\u0036\u0071\u0070\u0043\u003d\u005a\u0054\u002a\u0077\u004a\u0047\u0033\u006b\u0052\u004a\u0055\u0038\u002c\u003d\u0062\u004b\u005e\u004e\u003e\u004d\u0022\u0026\u002f\u004b\u0057\u0067\u0051\u0031\u002a\u0049\u002f\u004d\u007b\u0063\u0029\u007b\u0042\u0054\u006e\u006f\u0049\u0043\u0023\u0056\u006e\u007d\u0045\u0056\u0046\u0065\u0061\u0042\u0058\u0075\u0072\u0060\u0057\u0072\u0058\u0065\u004f\u003f\u005d\u0069\u0044\u0023\u0077\u003d\u005f\u0075\u003d\u0023\u003c\u0050\u0037\u0031\u0036\u007e\u002e\u005b\u0052\u004b\u003a\u005a\u0067\u005e\u004c\u0044\u0059\u0067\u0058\u0035\u0068\u0030\u003c\u005a\u006c\u007e\u006f\u0054\u003a\u006a\u003a\u007e\u0048\u0052\u0074\u0070\u0056\u0054\u0037\u0075\u0054\u004b\u0034\u0052\u003d\u0032\u0065\u006d\u0037\u004a\u006f\u0060\u0076\u0022\u0054\u005c\u002a\u002d\u002d\u006f\u007c\u006e\u0034\u0037\u0057\u005b\u004c\u0048\u0066\u0053\u0072\u007b\u0046\u0061\u005f\u007c\u0027\u0022\u0072\u0035\u0070\u002b\u0038\u002b\u0021\u004e\u005f\u006b\u0063\u0072\u0037\u0066\u0051\u0051\u007e\u006c\u0060\u0054\u0065\u007c\u0031\u003d\u0024\u0056\u006a\u0031\u007a\u0024\u0071\u006f\u004b\u005e\u0067\u0067\u0054\u0067\u0027\u0062\u0055\u0066\u0064\u005d\u003e\u006f\u0057\u0021\u0039\u0032\u0056\u005b\u0026\u0040\u006a\u0064\u0028\u006a\u004b\u0025\u0047\u0060\u0021\u0046\u0064\u0064\u0020\u006a\u004e\u0050\u0065\u0050\u0061\u005e\u003f\u0053\u0034\u0032\u007c\u0028\u0065\u0072\u004b\u002c\u0067\u0031\u0065\u0040\u004f\u0038\u0061\u002d\u002f\u007c\u0078\u003f\u0033\u005f\u0052\u0054\u0057\u004f\u0024\u0069\u003f\u005f\u0059\u0024\u006e\u005f\u0036\u0048\u004c\u004f\u0057\u003b\u0072\u0067\u006d\u0064\u004b\u0026\u002a\u002a\u0052\u0059\u0039\u005b\u003e\u0032\u0021\u007a\u0055\u007e\u005a\u0033\u0075\u004d\u006a\u0066\u006b\u0048\u0039\u0030\u0069\u0023\u0023\u0070\u005f\u007d\u003f\u003d\u0079\u0058\u0075\u0041\u0075\u005a\u0025\u004e\u004b\u0045\u0059\u0042\u004a\u0044\u005f\u0068\u007a\u0023\u007a\u007d\u0036\u002c\u0025\u0046\u0067\u003f\u0073\u004f\u0039\u005c\u0071\u004e\u0023\u0066\u003e\u004a\u003b\u0059\u007a\u0073\u0043\u002c\u0051\u0034\u0060\u0067\u0077\u0045\u0024\u007d\u0064\u007d\u0020\u0063\u006e\u0066\u003a\u0070\u0072\u0070\u006c\u003f\u0068\u007e\u0071\u003e\u0026\u0031\u0028\u0068\u0027\u005a\u0031\u004a\u006e\u004f\u0051\u003d\u002e\u007d\u0039\u002a\u0050\u0059\u002b\u003d\u0059\u0045\u0037\u005f\u0074\u005f\u0053\u004d\u0078\u002e\u005d\u004d\u004b\u0049\u0073\u0039\u0066\u0049\u0072\u0056\u0020\u006f\u0021\u005b\u0074\u0030\u0048\u003c\u007c\u0028\u0027\u0054\u003b\u004f\u005e\u0055\u005c\u0024\u0074\u0074\u0055\u0054\u0064\u003c\u0058\u007c\u006a\u0037\u0046\u005c\u0071\u0065\u0076\u0058\u0031\u0052\u0050\u003a\u003a\u0059\u0076\u0041\u005d\u0022\u0022\u002d\u0069\u0022\u0063\u004b\u0072\u0034\u0026\u0069\u007c\u003d\u002c\u006d\u0031\u0042\u0042\u0034\u0055\u0078\u0056\u0063\u0045\u004d\u0040\u0061\u006f\u004e\u006b\u0039\u0023\u005b\u005c\u0040\u002a\u003a\u0047\u005c\u004f\u0047\u007a\u0073\u0036\u0067\u0039\u0076\u0067\u0042\u0022\u0071\u0046\u0042\u007a\u0053\u004f\u0049\u0067\u0072\u0066\u007e\u004a\u007c\u0035\u0070\u007a\u0060\u0020\u0057\u0027\u0054\u0028\u007a\u0053\u0046\u0037\u0044\u0032\u004f\u0031\u0021\u004b\u0031\u007d\u0067\u0072\u0042\u0065\u0046\u0049\u0030\u0077\u007e\u0064\u0036\u003f\u0061\u0036\u007b\u005a\u0057\u0053\u007b\u0077\u0063\u0058\u0062\u006a\u003f\u0044\u0041\u007b\u0035\u0055\u003a\u002f\u0044\u004e\u007c\u0053\u003b\u0070\u0067\u0032\u007b\u002a\u0025\u0058\u0053\u0035\u0075\u0042\u0039\u0059\u0057\u002c\u0038\u0023\u003c\u0073\u0075\u002a\u004f\u0022\u002a\u007a\u0076\u004b\u0062\u0077\u004c\u0045\u0055\u0066\u005c\u0041\u005f\u0023\u0055\u007b\u0042\u0067\u002b\u0036\u0045\u0027\u003c\u0051\u0060\u003a\u005e\u0038\u0047\u006c\u0022\u007a\u0033\u0048\u0041\u007d\u004c\u0043\u002d\u007a\u0044\u0061\u0055\u0049\u005f\u007a\u0037\u0057\u0079\u0029\u0062\u003d\u004b\u007d\u0079\u0075\u0033\u0065\u005e\u0056\u0054\u0050\u0076\u0075\u006f\u005c\u005a\u0043\u0050\u005d\u004b\u0058\u002b\u0044\u0035\u0030\u005b\u0072\u003d\u0047\u0067\u005f\u0046\u003f\u0059\u0027\u0060\u0070\u004c\u002d\u0073\u0061\u0078\u0041\u0057\u006d\u0029\u0079\u005e\u003a\u0034\u0037\u0056\u004f\u0049\u006f\u0035\u0069\u006f\u004a\u004c\u0047\u0049\u0079\u0078\u0024\u007c\u002f\u007a\u0043\u0026\u0023\u0052\u002e\u0037\u003c\u0070\u0021\u0033\u0045\u006b\u0061\u0071\u002a\u0046\u0066\u0053\u007d\u0023\u006e\u0072\u0036\u0056\u003c\u0074\u004d\u0071\u0036\u0030\u0075\u0027\u0051\u0049\u0063\u0058